% block default rule of U iff some exception targets U (negation-as-failure)
blocked(U) :- exception_of(_, U).
holds(U) :- in_force(U), not blocked(U).

% rule BLDS2015.D609.R1 (source BLDS2015.D609): Cá nhân có quyền lập di chúc để định đoạt tài sản của mình
conclusion('BLDS2015.D609.R1') :- in_force('BLDS2015.D609'), premise('BLDS2015.D609.R1', 'Chủ thể là cá nhân'), not blocked('BLDS2015.D609').
premise('BLDS2015.D609.R1', 'Chủ thể là cá nhân').

% rule BLDS2015.D609.R2 (source BLDS2015.D609): Cá nhân có quyền để lại tài sản của mình cho người thừa kế theo pháp luật
conclusion('BLDS2015.D609.R2') :- in_force('BLDS2015.D609'), premise('BLDS2015.D609.R2', 'Chủ thể là cá nhân'), not blocked('BLDS2015.D609').
premise('BLDS2015.D609.R2', 'Chủ thể là cá nhân').

% rule BLDS2015.D609.R3 (source BLDS2015.D609): Cá nhân có quyền hưởng di sản theo di chúc hoặc theo pháp luật
conclusion('BLDS2015.D609.R3') :- in_force('BLDS2015.D609'), premise('BLDS2015.D609.R3', 'Chủ thể là cá nhân'), not blocked('BLDS2015.D609').
premise('BLDS2015.D609.R3', 'Chủ thể là cá nhân').

% rule BLDS2015.D609.R4 (source BLDS2015.D609): Người thừa kế không là cá nhân có quyền hưởng di sản theo di chúc
conclusion('BLDS2015.D609.R4') :- in_force('BLDS2015.D609'), premise('BLDS2015.D609.R4', 'Chủ thể là người thừa kế'), premise('BLDS2015.D609.R4', 'Chủ thể không là cá nhân'), not blocked('BLDS2015.D609').
premise('BLDS2015.D609.R4', 'Chủ thể là người thừa kế').
premise('BLDS2015.D609.R4', 'Chủ thể không là cá nhân').

